#include "tigersheets/workbook_tools.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool okay,const char* message){if(!okay)throw std::runtime_error(message);}
Json edit(int col,const std::string& value){return Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",col},{"input",value}}});}
void sharedProposalState(){WorkbookSession session;WorkbookTools tools(session,Json::object());require(tools.invoke("workbook_v1_preview",{{"revision",0},{"operations",edit(1,"first")}}).value("status",std::string())=="preview","initial branch is a preview");const auto original=tools.proposalState(),shared=original;require(original.baseRevision==0&&original.operations&&original.operations->size()==1&&shared.operations.get()==original.operations.get(),"capturing proposal state shares immutable operations without cloning them");
 WorkbookSession isolated(session.snapshot());require(!isolated.preview(0,*original.operations).is_null(),"worker replays the previous branch off process");WorkbookTools worker(isolated,Json::object());require(worker.adoptProposal(original),"worker adopts the previous immutable proposal");require(worker.invoke("workbook_v1_preview",{{"revision",0},{"operations",edit(2,"second")}}).value("status",std::string())=="preview","worker composes another preview call");const auto updated=worker.proposalState();require(updated.operations->size()==2&&original.operations->size()==1,"new proposals do not mutate shared previous operations");
 auto prepared=WorkbookSession::prepareTransaction(session.snapshot(),*updated.operations);const auto* moved=&prepared->snapshot()["sheets"][0]["cells"][0];require(session.previewPrepared(0,prepared)&&tools.adoptProposal(updated),"host adopts the worker's prepared candidate and shared branch state");require(&session.previewView()->at("sheets")[0].at("cells")[0]==moved&&tools.proposalState().operations.get()==updated.operations.get(),"UI branch adoption copies neither candidate cells nor expanded cache operations");
 const auto read=tools.invoke("workbook_v1_read",Json::object());require(read.at("view")=="preview"&&read.at("sheets")[0]["cells"].size()==2&&session.snapshotView()["sheets"][0]["cells"].empty(),"bounded reads use Session.previewView after state transfer");std::unique_ptr<WorkbookSession::PreparedTransaction> retired;require(session.acceptPrepared(retired),"accept transferred prepared branch");tools.invoke("workbook_v1_read",Json::object());require(tools.proposalState().operations->empty(),"acceptance resets accumulated tool operations without changing old shared state");
 WorkbookSession foreign;require(foreign.apply(0,edit(3,"newer")),"advance foreign workbook revision");WorkbookTools other(foreign,Json::object());require(!other.adoptProposal(original),"proposal state cannot attach to a different revision or missing preview");
}
int main(){try{sharedProposalState();std::cout<<"tool proposal state tests passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
